-- ==========================================================================
-- LacakIn v2 - Data Detail Wilayah Jawa Timur (Kemendagri)
-- Total: 666 Kecamatan & 8494 Kelurahan/Desa
-- + Kolom terstruktur RT/RW/Kecamatan/Kelurahan pada shipments & users
-- Idempotent: aman dijalankan berulang kali.
-- ==========================================================================

CREATE TABLE IF NOT EXISTS districts (
    id      SERIAL PRIMARY KEY,
    city_id INTEGER NOT NULL REFERENCES cities(id) ON DELETE CASCADE,
    code    TEXT UNIQUE NOT NULL,
    name    TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS villages (
    id          SERIAL PRIMARY KEY,
    district_id INTEGER NOT NULL REFERENCES districts(id) ON DELETE CASCADE,
    code        TEXT UNIQUE NOT NULL,
    name        TEXT NOT NULL,
    type        TEXT NOT NULL DEFAULT 'DESA' CHECK (type IN ('KELURAHAN', 'DESA')),
    postal_code TEXT
);

CREATE INDEX IF NOT EXISTS idx_districts_city    ON districts (city_id);
CREATE INDEX IF NOT EXISTS idx_villages_district ON villages (district_id);
CREATE INDEX IF NOT EXISTS idx_villages_postal   ON villages (postal_code);

-- Kolom alamat terstruktur pada shipments & users
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS origin_district_id INTEGER REFERENCES districts(id);
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS origin_village_id  INTEGER REFERENCES villages(id);
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS origin_rt          VARCHAR(5);
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS origin_rw          VARCHAR(5);
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS origin_postal_code VARCHAR(10);
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS dest_district_id   INTEGER REFERENCES districts(id);
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS dest_village_id    INTEGER REFERENCES villages(id);
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS dest_rt            VARCHAR(5);
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS dest_rw            VARCHAR(5);
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS dest_postal_code   VARCHAR(10);

ALTER TABLE users ADD COLUMN IF NOT EXISTS city_id        INTEGER REFERENCES cities(id);
ALTER TABLE users ADD COLUMN IF NOT EXISTS district_id    INTEGER REFERENCES districts(id);
ALTER TABLE users ADD COLUMN IF NOT EXISTS village_id     INTEGER REFERENCES villages(id);
ALTER TABLE users ADD COLUMN IF NOT EXISTS street_address TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS rt             VARCHAR(5);
ALTER TABLE users ADD COLUMN IF NOT EXISTS rw             VARCHAR(5);
ALTER TABLE users ADD COLUMN IF NOT EXISTS postal_code    VARCHAR(10);

