INSERT INTO villages (district_id, code, name, type, postal_code)
SELECT dist.id, v.code, v.name, v.type, v.postal_code FROM v JOIN districts dist ON dist.code = v.district_code
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, postal_code = COALESCE(EXCLUDED.postal_code, villages.postal_code);

